import{_ as o,a0 as l,w as d,s as r,ao as p,I as e,x as n,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序 | LCTT x X-CMD","titleTemplate":false,"description":"動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20130402 Dynamic linker tricks Using LD_PRELOAD to cheat inject features and investigate programs","title":"動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序","tag":"201712","desc":""},"relativePath":"201712/20130402 Dynamic linker tricks Using LD_PRELOAD to cheat inject features and investigate programs.md","filePath":"[post].md"}'),c={name:"201712/20130402 Dynamic linker tricks Using LD_PRELOAD to cheat inject features and investigate programs.md"};function g(h,s,u,k,b,m){const a=l("Link");return d(),r("div",null,[s[20]||(s[20]=p(`<h1 id="動態連接的訣竅-使用-ld-preload-去欺騙、注入特性和研究程序" tabindex="-1">動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序 <a class="header-anchor" href="#動態連接的訣竅-使用-ld-preload-去欺騙、注入特性和研究程序" aria-label="Permalink to “動態連接的訣竅：使用 LD_PRELOAD 去欺騙、注入特性和研究程序”">​</a></h1><p><strong>本文假設你具備基本的 C 技能</strong></p><p>Linux 完全在你的控制之中。雖然從每個人的角度來看似乎並不總是這樣，但是高級用户喜歡去控制它。我將向你展示一個基本的訣竅，在很大程度上你可以去影響大多數程序的行為，它並不僅是好玩，在有時候也很有用。</p><h3 id="一個讓我們產生興趣的示例" tabindex="-1">一個讓我們產生興趣的示例 <a class="header-anchor" href="#一個讓我們產生興趣的示例" aria-label="Permalink to “一個讓我們產生興趣的示例”">​</a></h3><p>讓我們以一個簡單的示例開始。先樂趣，後科學。</p><p><em>random_num.c：</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>int main(){</span></span>
<span class="line"><span>  srand(time(NULL));</span></span>
<span class="line"><span>  int i = 10;</span></span>
<span class="line"><span>  while(i--) printf(&quot;%d\\n&quot;,rand()%100);</span></span>
<span class="line"><span>  return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我相信，它足夠簡單吧。我不使用任何參數來編譯它，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc random_num.c -o random_num</span></span></code></pre></div><p>我希望它輸出的結果是明確的：從 0-99 中選擇的十個隨機數字，希望每次你運行這個程序時它的輸出都不相同。</p><p>現在，讓我們假裝真的不知道這個可執行程序的出處。甚至將它的源文件刪除，或者把它移動到別的地方 —— 我們已不再需要它了。我們將對這個程序的行為進行重大的修改，而你並不需要接觸到它的源代碼，也不需要重新編譯它。</p><p>因此，讓我們來創建另外一個簡單的 C 文件：</p><p><em>unrandom.c：</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int rand(){</span></span>
<span class="line"><span>    return 42; //the most random number in the universe</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我們將編譯它進入一個共享庫中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -shared -fPIC unrandom.c -o unrandom.so</span></span></code></pre></div><p>因此，現在我們已經有了一個可以輸出一些隨機數的應用程序，和一個定製的庫，它使用一個常數值 <code>42</code> 實現了一個 <code>rand()</code> 函數。現在 …… 就像運行 <code>random_num</code> 一樣，然後再觀察結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LD_PRELOAD=$PWD/unrandom.so ./random_nums</span></span></code></pre></div><p>如果你想偷懶或者不想自動親自動手（或者不知什麼原因猜不出發生了什麼），我來告訴你 —— 它輸出了十次常數 42。</p><p>如果先這樣執行</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export LD_PRELOAD=$PWD/unrandom.so</span></span></code></pre></div><p>然後再以正常方式運行這個程序，這個結果也許會更讓你吃驚：一個未被改變過的應用程序在一個正常的運行方式中，看上去受到了我們做的一個極小的庫的影響 ……</p><p><strong>等等，什麼？剛剛發生了什麼？</strong></p><p>是的，你説對了，我們的程序生成隨機數失敗了，因為它並沒有使用 “真正的” <code>rand()</code>，而是使用了我們提供的的那個 —— 它每次都返回 <code>42</code>。</p><p><strong>但是，我們<em>告訴過</em>它去使用真實的那個。我們編程讓它去使用真實的那個。另外，在創建那個程序的時候，假冒的 <code>rand()</code> 甚至並不存在！</strong></p><p>這句話並不完全正確。我們只能告訴它去使用 <code>rand()</code>，但是我們不能去選擇哪個 <code>rand()</code> 是我們希望我們的程序去使用的。</p><p>當我們的程序啓動後，（為程序提供所需要的函數的）某些庫被加載。我們可以使用 <code>ldd</code> 去學習它是怎麼工作的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd random_nums</span></span>
<span class="line"><span>linux-vdso.so.1 =&gt; (0x00007fff4bdfe000)</span></span>
<span class="line"><span>libc.so.6 =&gt; /lib/x86_64-linux-gnu/libc.so.6 (0x00007f48c03ec000)</span></span>
<span class="line"><span>/lib64/ld-linux-x86-64.so.2 (0x00007f48c07e3000)</span></span></code></pre></div><p>正如你看到的輸出那樣，它列出了被程序 <code>random_nums</code> 所需要的庫的列表。這個列表是構建進可執行程序中的，並且它是在編譯時決定的。在你的機器上的具體的輸出可能與示例有所不同，但是，一個 <code>libc.so</code> 肯定是有的 —— 這個文件提供了核心的 C 函數。它包含了 “真正的” <code>rand()</code>。</p><p>我使用下列的命令可以得到一個全部的函數列表，我們看一看 libc 提供了哪些函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nm -D /lib/libc.so.6</span></span></code></pre></div><p>這個 <code>nm</code>  命令列出了在一個二進制文件中找到的符號。<code>-D</code> 標誌告訴它去查找動態符號，因為 <code>libc.so.6</code> 是一個動態庫。這個輸出是很長的，但它確實在列出的很多標準函數中包括了 <code>rand()</code>。</p><p>現在，在我們設置了環境變量 <code>LD_PRELOAD</code> 後發生了什麼？這個變量 <strong>為一個程序強制加載一些庫</strong>。在我們的案例中，它為 <code>random_num</code> 加載了 <code>unrandom.so</code>，儘管程序本身並沒有這樣去要求它。下列的命令可以看得出來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ LD_PRELOAD=$PWD/unrandom.so ldd random_nums</span></span>
<span class="line"><span>linux-vdso.so.1 =&gt;  (0x00007fff369dc000)</span></span>
<span class="line"><span>/some/path/to/unrandom.so (0x00007f262b439000)</span></span>
<span class="line"><span>libc.so.6 =&gt; /lib/x86_64-linux-gnu/libc.so.6 (0x00007f262b044000)</span></span>
<span class="line"><span>/lib64/ld-linux-x86-64.so.2 (0x00007f262b63d000)</span></span></code></pre></div><p>注意，它列出了我們當前的庫。實際上這就是代碼為什麼得以運行的原因：<code>random_num</code> 調用了 <code>rand()</code>，但是，如果 <code>unrandom.so</code> 被加載，它調用的是我們所提供的實現了 <code>rand()</code> 的庫。很清楚吧，不是嗎？</p><h3 id="更清楚地瞭解" tabindex="-1">更清楚地瞭解 <a class="header-anchor" href="#更清楚地瞭解" aria-label="Permalink to “更清楚地瞭解”">​</a></h3><p>這還不夠。我可以用相似的方式注入一些代碼到一個應用程序中，並且用這種方式它能夠像個正常的函數一樣工作。如果我們使用一個簡單的 <code>return 0</code> 去實現 <code>open()</code> 你就明白了。我們看到這個應用程序就像發生了故障一樣。這是 <strong>顯而易見的</strong>， 真實地去調用原始的 <code>open()</code>：</p><p><em>inspect_open.c：</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int open(const char *pathname, int flags){</span></span>
<span class="line"><span>  /* Some evil injected code goes here. */</span></span>
<span class="line"><span>  return open(pathname,flags); // Here we call the &quot;real&quot; open function, that is provided to us by libc.so</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>嗯，不對。這將不會去調用 “原始的” <code>open(...)</code>。顯然，這是一個無休止的遞歸調用。</p><p>怎麼去訪問這個 “真正的” <code>open()</code> 函數呢？它需要去使用程序接口進行動態鏈接。它比聽起來更簡單。我們來看一個完整的示例，然後，我將詳細解釋到底發生了什麼：</p><p><em>inspect_open.c：</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#define _GNU_SOURCE</span></span>
<span class="line"><span>#include &lt;dlfcn.h&gt;</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>typedef int (*orig_open_f_type)(const char *pathname, int flags);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>int open(const char *pathname, int flags, ...)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    /* Some evil injected code goes here. */</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>    orig_open_f_type orig_open;</span></span>
<span class="line"><span>    orig_open = (orig_open_f_type)dlsym(RTLD_NEXT,&quot;open&quot;);</span></span>
<span class="line"><span>    return orig_open(pathname,flags);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>dlfcn.h</code> 是我們後面用到的 <code>dlsym</code> 函數所需要的。那個奇怪的 <code>#define</code> 是命令編譯器去允許一些非標準的東西，我們需要它來啓用 <code>dlfcn.h</code> 中的 <code>RTLD_NEXT</code>。那個 <code>typedef</code> 只是創建了一個函數指針類型的別名，它的參數等同於原始的 <code>open</code> —— 它現在的別名是 <code>orig_open_f_type</code>，我們將在後面用到它。</p><p>我們定製的 <code>open(...)</code> 的主體是由一些代碼構成。它的最後部分創建了一個新的函數指針 <code>orig_open</code>，它指向原始的 <code>open(...)</code> 函數。為了得到那個函數的地址，我們請求 <code>dlsym</code> 在動態庫堆棧上為我們查找下一個 <code>open()</code> 函數。最後，我們調用了那個函數（傳遞了與我們的假冒 <code>open()</code> 一樣的參數），並且返回它的返回值。</p><p>我使用下面的內容作為我的 “邪惡的注入代碼”：</p><p><em>inspect_open.c (片段)：</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf(&quot;The victim used open(...) to access &#39;%s&#39;!!!\\n&quot;,pathname); //remember to include stdio.h!</span></span></code></pre></div><p>要編譯它，我需要稍微調整一下編譯參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -shared -fPIC  inspect_open.c -o inspect_open.so -ldl</span></span></code></pre></div><p>我增加了 <code>-ldl</code>，因此，它將這個共享庫鏈接到 <code>libdl</code> —— 它提供了 <code>dlsym</code> 函數。（不，我還沒有創建一個假冒版的 <code>dlsym</code> ，雖然這樣更有趣）</p><p>因此，結果是什麼呢？一個實現了 <code>open(...)</code> 函數的共享庫，除了它有 <em>輸出</em> 文件路徑的意外作用以外，其它的表現和真正的 <code>open(...)</code> 函數 <strong>一模一樣</strong>。😃</p><p>如果這個強大的訣竅還沒有説服你，是時候去嘗試下面的這個示例了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LD_PRELOAD=$PWD/inspect_open.so gnome-calculator</span></span></code></pre></div><p>我鼓勵你去看看自己實驗的結果，但是簡單來説，它實時列出了這個應用程序可以訪問到的每個文件。</p><p>我相信它並不難想像為什麼這可以用於去調試或者研究未知的應用程序。請注意，這個特定訣竅並不完整，因為 <code>open()</code> 並不是唯一一個打開文件的函數 …… 例如，在標準庫中也有一個 <code>open64()</code>，並且為了完整地研究，你也需要為它去創建一個假冒的。</p><h3 id="可能的用法" tabindex="-1">可能的用法 <a class="header-anchor" href="#可能的用法" aria-label="Permalink to “可能的用法”">​</a></h3><p>如果你一直跟着我享受上面的過程，讓我推薦一個使用這個訣竅能做什麼的一大堆創意。記住，你可以在不損害原始應用程序的同時做任何你想做的事情！</p>`,58)),e("ol",null,[s[4]||(s[4]=p("<li><s>獲得 root 權限</s>。你想多了！你不會通過這種方法繞過安全機制的。（一個專業的解釋是：如果 ruid != euid，庫不會通過這種方法預加載的。）</li><li>欺騙遊戲：<strong>取消隨機化</strong>。這是我演示的第一個示例。對於一個完整的工作案例，你將需要去實現一個定製的 <code>random()</code> 、<code>rand_r()</code>、<code>random_r()</code>，也有一些應用程序是從 <code>/dev/urandom</code> 之類的讀取，你可以通過使用一個修改過的文件路徑來運行原始的 <code>open()</code> 來把它們重定向到 <code>/dev/null</code>。而且，一些應用程序可能有它們自己的隨機數生成算法，這種情況下你似乎是沒有辦法的（除非，按下面的第 10 點去操作）。但是對於一個新手來説，它看起來很容易上手。</li><li>欺騙遊戲：<strong>讓子彈飛一會</strong> 。實現所有的與時間有關的標準函數，讓假冒的時間變慢兩倍，或者十倍。如果你為時間測量和與時間相關的 <code>sleep</code> 或其它函數正確地計算了新的值，那麼受影響的應用程序將認為時間變慢了（你想的話，也可以變快），並且，你可以體驗可怕的 “子彈時間” 的動作。或者 <strong>甚至更進一步</strong>，你的共享庫也可以成為一個 DBus 客户端，因此你可以使用它進行實時的通訊。綁定一些快捷方式到定製的命令，並且在你的假冒的時間函數上使用一些額外的計算，讓你可以有能力按你的意願去啓用和禁用慢進或快進任何時間。</li><li>研究應用程序：<strong>列出訪問的文件</strong>。它是我演示的第二個示例，但是這也可以進一步去深化，通過記錄和監視所有應用程序的文件 I/O。</li><li>研究應用程序：<strong>監視因特網訪問</strong>。你可以使用 Wireshark 或者類似軟件達到這一目的，但是，使用這個訣竅你可以真實地控制基於 web 的應用程序發送了什麼，不僅是看看，而是也能影響到交換的數據。這裏有很多的可能性，從檢測間諜軟件到欺騙多用户遊戲，或者分析和逆向工程使用閉源協議的應用程序。</li><li>研究應用程序：<strong>檢查 GTK 結構</strong> 。為什麼只侷限於標準庫？讓我們在所有的 GTK 調用中注入一些代碼，因此我們就可以知道一個應用程序使用了哪些組件，並且，知道它們的構成。然後這可以渲染出一個圖像或者甚至是一個 gtkbuilder 文件！如果你想去學習一些應用程序是怎麼管理其界面的，這個方法超級有用！</li><li><strong>在沙盒中運行不安全的應用程序</strong>。如果你不信任一些應用程序，並且你可能擔心它會做一些如 <code>rm -rf /</code> 或者一些其它不希望的文件活動，你可以通過修改傳遞到文件相關的函數（不僅是 <code>open</code> ，也包括刪除目錄等）的參數，來重定向所有的文件 I/O 操作到諸如 <code>/tmp</code> 這樣地方。還有更難的訣竅，如 chroot，但是它也給你提供更多的控制。它可以更安全地完全 “封裝”，但除非你真的知道你在做什麼，不要以這種方式真的運行任何惡意軟件。</li>",7)),e("li",null,[s[1]||(s[1]=e("strong",null,"實現特性",-1)),s[2]||(s[2]=n(" 。",-1)),i(a,{href:"http://www.zlibc.linux.lu/index.html"},{default:t(()=>[...s[0]||(s[0]=[n("zlibc",-1)])]),_:1}),s[3]||(s[3]=n(" 是明確以這種方法運行的一個真實的庫；它可以在訪問文件時解壓文件，因此，任何應用程序都可以在無需實現解壓功能的情況下訪問壓縮數據。",-1))]),s[5]||(s[5]=e("li",null,[e("strong",null,"修復 bug"),n("。另一個現實中的示例是：不久前（我不確定現在是否仍然如此）Skype（它是閉源的軟件）從某些網絡攝像頭中捕獲視頻有問題。因為 Skype 並不是自由軟件，源文件不能被修改，這就可以通過使用預加載一個解決了這個問題的庫的方式來修復這個 bug。")],-1)),s[6]||(s[6]=e("li",null,[n("手工方式 "),e("strong",null,"訪問應用程序擁有的內存"),n("。請注意，你可以通過這種方式去訪問所有應用程序的數據。如果你有類似的軟件，如 CheatEngine/scanmem/GameConqueror 這可能並不會讓人驚訝，但是，它們都要求 root 權限才能工作，而 "),e("code",null,"LD_PRELOAD"),n(" 則不需要。事實上，通過一些巧妙的訣竅，你注入的代碼可以訪問所有的應用程序內存，從本質上看，是因為它是通過應用程序自身得以運行的。你可以修改這個應用程序能修改的任何東西。你可以想像一下，它允許你做許多的底層的侵入…… ，但是，關於這個主題，我將在某個時候寫一篇關於它的文章。")],-1))]),s[21]||(s[21]=e("p",null,"這裏僅是一些我想到的創意。我希望你能找到更多，如果你做到了 —— 通過下面的評論區共享出來吧！",-1)),s[22]||(s[22]=e("hr",null,null,-1)),e("p",null,[s[8]||(s[8]=n("via: ",-1)),i(a,{href:"https://rafalcieslak.wordpress.com/2013/04/02/dynamic-linker-tricks-using-ld_preload-to-cheat-inject-features-and-investigate-programs/"},{default:t(()=>[...s[7]||(s[7]=[n("https://rafalcieslak.wordpress.com/2013/04/02/dynamic-linker-tricks-using-ld_preload-to-cheat-inject-features-and-investigate-programs/",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=n("作者：",-1)),i(a,{href:"https://rafalcieslak.wordpress.com/"},{default:t(()=>[...s[9]||(s[9]=[n("Rafał Cieślak",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),i(a,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[10]||(s[10]=[n("qhwdw",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const C=o(c,[["render",g]]);export{y as __pageData,C as default};
